function jobSequencing(jobs) {
  jobs.sort((a, b) => b.profit - a.profit);
  const maxDeadline = Math.max(...jobs.map(j => j.deadline));
  const slots = new Array(maxDeadline + 1).fill(null);
  let totalProfit = 0;
  for (const job of jobs) {
    for (let t = job.deadline; t > 0; t--) {
      if (!slots[t]) {
        slots[t] = job.id;
        totalProfit += job.profit;
        break;
      }
    }
  }
  return { totalProfit, sequence: slots.filter(Boolean)};
}

const jobs = [ { id: 'a', deadline: 2, profit: 100 }, { id: 'b', deadline: 1, profit: 19 }, { id: 'c', deadline: 2, profit: 27 }, { id: 'd', deadline: 1, profit: 25 }, { id: 'e', deadline: 3, profit: 15 }, ];
