#include <stdio.h>
#include <stdlib.h>
typedef struct {
    int id, profit, deadline;
} Job;
int cmp(const void*a, const void*b) {
    return ((Job*)b)->profit-((Job*)a)->profit;
}
void schedule(Job jobs[], int n) {
    qsort(jobs, n, sizeof(Job), cmp);
    int slot[n+1], p=0, c=0;
    for (int i=0; i<=n; i++)slot[i]=-1;
    for (int i=0; i<n; i++)for (int j=jobs[i].deadline; j>=1; j--)if (slot[j]==-1) {
        slot[j]=jobs[i].id;
        p+=jobs[i].profit;
        c++;
        break;
    }
    printf("%d jobs, profit=%d\n", c, p);
}

