pair<int, int> scheduleJobs(vector<int>&p, vector<int>&d) {
    int n=p.size(), mx=*max_element(d.begin(), d.end());
    vector<int>idx(n), slot(mx+1, -1);
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int a, int b){return p[a]>p[b]; });
    int profit=0, cnt=0;
    for (int i:idx)for (int j=d[i]; j>=1; j--)if (slot[j]==-1) {
        slot[j]=i;
        profit+=p[i];
        cnt++;
        break;
    }
    return {cnt, profit};
}
